SELECT TAREA.ID_TAREA AS ID_TAREA, CAST(:idAlgoritmo AS BIGINT) AS ID_ALGORITMO, TRABAJO.ID_SOCIEDAD AS ID_SOCIEDAD, TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AS FECHA, EMPLEADO_HISTORICO.ID_EMPLEADO AS ID_EMPLEADO, EMPLEADO_HISTORICO.ID_EMPLEADO_LOCAL AS ID_EMPLEADO_LOCAL, EMPLEADO_HISTORICO.OR_EMPLEADO AS OR_EMPLEADO, TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.STD_ID_WORK_LOCAT AS ID_TIENDA, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.STD_ID_WORK_LOCAT AS ID_TIENDA_PRESENCIA, TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.CCL_ID_COD_ORIGEN AS ID_TIENDA_MTU, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.CCL_ID_COD_ORIGEN AS ID_TIENDA_PRESENCIA_MTU, EMPLEADO_HISTORICO.ID_SECCION AS ID_SECCION_EMPLEADO, EMPLEADO_ESTRUCTURA.PORCENTAJE AS COMISION_PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_1 AS COMISION_PORCENTAJE_SECCION_1, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_2 AS COMISION_PORCENTAJE_SECCION_2, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_3 AS COMISION_PORCENTAJE_SECCION_3, TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 AS EMPLEADO_PRESENCIA_MINUTOS_SECCION_1, TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 AS EMPLEADO_PRESENCIA_MINUTOS_SECCION_2, TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 AS EMPLEADO_PRESENCIA_MINUTOS_SECCION_3, TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 AS TIENDA_PRESENCIA_MINUTOS_SECCION_1, TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 AS TIENDA_PRESENCIA_MINUTOS_SECCION_2, TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 AS TIENDA_PRESENCIA_MINUTOS_SECCION_3, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_1 AS TIENDA_VENTA_IMPORTE_SECCION_1, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_2 AS TIENDA_VENTA_IMPORTE_SECCION_2, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_3 AS TIENDA_VENTA_IMPORTE_SECCION_3, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_1 AS TIENDA_VENTA_IMPORTE_CON_IMPUESTOS_SECCION_1, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_2 AS TIENDA_VENTA_IMPORTE_CON_IMPUESTOS_SECCION_2, TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_3 AS TIENDA_VENTA_IMPORTE_CON_IMPUESTOS_SECCION_3, /*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_1) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_SECCION_1,
/*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_2) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_SECCION_2,
/*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_3) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_SECCION_3,
/*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_1) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_CON_IMPUESTOS_SECCION_1,
/*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_2) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_CON_IMPUESTOS_SECCION_2,
/*PRECISION_INI*/ /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.IMPORTE_CON_IMPUESTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ (COALESCE(EMPLEADO_ESTRUCTURA.PORCENTAJE, EMPLEADO_ESTRUCTURA.PORCENTAJE_SECCION_3) / 100) /*PRECISION*/ /*PRECISION_FIN*/ * /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_EMPLEADO_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ / /*PRECISION_INI*/ ( /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_1 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_2 /*PRECISION*/ /*PRECISION_FIN*/ + /*PRECISION_INI*/ TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.MINUTOS_SECCION_3 /*PRECISION*/ /*PRECISION_FIN*/ ) /*PRECISION*/ /*PRECISION_FIN*/ /*PRECISION*/ /*PRECISION_FIN*/ AS IMPORTE_CON_IMPUESTOS_SECCION_3,
EMPLEADO_ESTRUCTURA.ID_ESTRUCTURA AS ID_ESTRUCTURA, EMPLEADO_ESTRUCTURA.ID_TIPO_CALCULO AS ID_TIPO_CALCULO, EMPLEADO_ESTRUCTURA.ID_TIPO_COMISION AS ID_TIPO_COMISION, TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_TIPO_HORA AS ID_TIPO_HORA FROM TAREA INNER JOIN TRABAJO ON TAREA.ID_TRABAJO = TRABAJO.ID_TRABAJO INNER JOIN TAREA_TIENDA_EMPLEADO_PRESENCIA_SECCION TIENDA_EMPLEADO_PRESENCIA_SECCION ON TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_TAREA = TAREA.ID_TAREA AND TIENDA_EMPLEADO_PRESENCIA_SECCION.ACTIVO = 1 AND TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_TIPO_DATO IN (37, 38) INNER JOIN TAREA_TIPO_HORA AS TIENDA_EMPLEADO_PRESENCIA_SECCION_TIPO_HORA ON TIENDA_EMPLEADO_PRESENCIA_SECCION_TIPO_HORA.ID_TAREA = TAREA.ID_TAREA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIPO_HORA.ID_TIPO_HORA = TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_TIPO_HORA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIPO_HORA.EXCLUIDO_CALCULO = 0 INNER JOIN TAREA_TIENDA_HISTORICO TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO ON TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.ID_TAREA = TAREA.ID_TAREA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.CCL_ID_COD_ORIGEN = TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_TIENDA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.FECHA_INICIO <= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.FECHA_FIN >= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA /* INNER JOIN TAREA_LOCALIZACION_CALCULAR TIENDA_CALCULAR ON TIENDA_CALCULAR.ID_TAREA = TAREA.ID_TAREA AND TIENDA_CALCULAR.ID_LOCALIZACION = TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.STD_ID_WORK_LOCAT AND TIENDA_CALCULAR.CALCULA = 1 */ INNER JOIN TAREA_TIENDA_COMISION_HISTORICO TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO ON TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO.ID_TAREA = TAREA.ID_TAREA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO.STD_ID_WORK_LOCAT = TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.STD_ID_WORK_LOCAT AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO.FECHA_INICIO <= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO.FECHA_FIN >= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_COMISION_HISTORICO.COMISIONABLE = 1 INNER JOIN TAREA_PERSONA_HISTORICO EMPLEADO_HISTORICO ON EMPLEADO_HISTORICO.ID_TAREA = TAREA.ID_TAREA AND EMPLEADO_HISTORICO.ID_EMPLEADO_LOCAL = TIENDA_EMPLEADO_PRESENCIA_SECCION.ID_EMPLEADO AND EMPLEADO_HISTORICO.FECHA_INICIO <= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND EMPLEADO_HISTORICO.FECHA_FIN >= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA INNER JOIN TAREA_TIENDA_HISTORICO TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO ON TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.ID_TAREA = TAREA.ID_TAREA AND TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.STD_ID_WORK_LOCAT = EMPLEADO_HISTORICO.STD_ID_WORK_LOCAT AND TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.FECHA_INICIO <= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TAREA_EMPLEADO_HISTORICO_TIENDA_HISTORICO.FECHA_FIN >= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA INNER JOIN TAREA_EMPLEADO_ESTRUCTURA AS EMPLEADO_ESTRUCTURA ON EMPLEADO_ESTRUCTURA.ID_TAREA = TAREA.ID_TAREA AND EMPLEADO_ESTRUCTURA.ID_EMPLEADO = EMPLEADO_HISTORICO.ID_EMPLEADO AND EMPLEADO_ESTRUCTURA.ID_EMPLEADO_LOCAL = EMPLEADO_HISTORICO.ID_EMPLEADO_LOCAL AND EMPLEADO_ESTRUCTURA.OR_EMPLEADO = EMPLEADO_HISTORICO.OR_EMPLEADO AND EMPLEADO_ESTRUCTURA.FECHA_INICIO <= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND EMPLEADO_ESTRUCTURA.FECHA_FIN >= TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND EMPLEADO_ESTRUCTURA.ID_TIPO_CALCULO = 1 /*AND EMPLEADO_ESTRUCTURA.ID_TIPO_COMISION = 1*/ INNER JOIN TAREA_TIENDA_VENTA_SECCION TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION ON TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.ID_TAREA = TAREA.ID_TAREA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.ID_TIENDA = TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.CCL_ID_COD_ORIGEN AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.FECHA = TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_VENTA_SECCION.ID_TIPO_DATO = 2 INNER JOIN TAREA_TIENDA_PRESENCIA_SECCION TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION ON TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.ID_TAREA = TAREA.ID_TAREA AND TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.ID_TIENDA = TIENDA_EMPLEADO_PRESENCIA_SECCION_TIENDA_HISTORICO.CCL_ID_COD_ORIGEN AND TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.FECHA = TIENDA_EMPLEADO_PRESENCIA_SECCION.FECHA AND TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.ACTIVO = 1 AND TIENDA_HISTORICO_TIENDA_PRESENCIA_SECCION.ID_TIPO_DATO IN (36, 39)
